# FILE: Chart.yaml
apiVersion: v2
name: stateful-app-with-migration
description: A Helm chart for a stateful application with database migration
type: application
version: 1.0.0
appVersion: "1.0.0"

---
# FILE: values.yaml
# Default values for stateful-app-with-migration chart

# Application configuration
app:
  name: myapp
  image:
    repository: myapp/image
    tag: latest
    pullPolicy: IfNotPresent
  replicas: 3
  containerPort: 8080
  resources:
    limits:
      cpu: 500m
      memory: 512Mi
    requests:
      cpu: 200m
      memory: 256Mi
  env: []
  args: []

# Migration configuration
migration:
  enabled: true
  image:
    repository: migrate/migrate
    tag: latest
    pullPolicy: IfNotPresent
  command: []
  args: []
  env: []
  resources:
    limits:
      cpu: 200m
      memory: 256Mi
    requests:
      cpu: 100m
      memory: 128Mi

# Database configuration
database:
  host: postgresql
  port: 5432
  name: myapp
  user: myapp
  password: myapp123

# Persistence configuration
persistence:
  enabled: true
  size: 10Gi
  accessModes:
    - ReadWriteOnce
  storageClassName: ""

# Service configuration
service:
  port: 8080
  targetPort: 8080

# Security context
securityContext:
  runAsNonRoot: true
  runAsUser: 1000
  fsGroup: 2000

---
# FILE: templates/migration-job.yaml
{{- if .Values.migration.enabled }}
apiVersion: batch/v1
kind: Job
metadata:
  name: {{ include "stateful-app-with-migration.fullname" . }}-migration
  labels:
    {{- include "stateful-app-with-migration.labels" . | nindent 4 }}
  annotations:
    "helm.sh/hook": pre-install,pre-upgrade
    "helm.sh/hook-weight": "-5"
    "helm.sh/hook-delete-policy": before-hook-creation
spec:
  template:
    metadata:
      labels:
        {{- include "stateful-app-with-migration.selectorLabels" . | nindent 8 }}
    spec:
      restartPolicy: Never
      containers:
        - name: migration
          image: "{{ .Values.migration.image.repository }}:{{ .Values.migration.image.tag }}"
          imagePullPolicy: {{ .Values.migration.image.pullPolicy }}
          command:
            {{- range .Values.migration.command }}
            - {{ . | quote }}
            {{- end }}
          args:
            {{- range .Values.migration.args }}
            - {{ . | quote }}
            {{- end }}
          env:
            {{- range .Values.migration.env }}
            - name: {{ .name }}
              value: {{ .value | quote }}
            {{- end }}
            - name: DATABASE_URL
              value: postgres://{{ .Values.database.user }}:{{ .Values.database.password }}@{{ .Values.database.host }}:{{ .Values.database.port }}/{{ .Values.database.name }}?sslmode=disable
          resources:
            {{- toYaml .Values.migration.resources | nindent 12 }}
      {{- with .Values.securityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
{{- end }}

---
# FILE: templates/statefulset.yaml
apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: {{ include "stateful-app-with-migration.fullname" . }}
  labels:
    {{- include "stateful-app-with-migration.labels" . | nindent 4 }}
spec:
  serviceName: {{ include "stateful-app-with-migration.fullname" . }}-headless
  replicas: {{ .Values.app.replicas }}
  selector:
    matchLabels:
      {{- include "stateful-app-with-migration.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "stateful-app-with-migration.selectorLabels" . | nindent 8 }}
    spec:
      {{- if .Values.migration.enabled }}
      initContainers:
        - name: wait-for-migration
          image: busybox:1.35
          command:
            - sh
            - -c
            - |
              echo "Waiting for migration job to complete..."
              until [ -f /tmp/migration-complete ]; do
                sleep 2
              done
              echo "Migration completed, starting application..."
          volumeMounts:
            - name: migration-status
              mountPath: /tmp
      {{- end }}
      containers:
        - name: {{ .Chart.Name }}
          image: "{{ .Values.app.image.repository }}:{{ .Values.app.image.tag }}"
          imagePullPolicy: {{ .Values.app.image.pullPolicy }}
          ports:
            - containerPort: {{ .Values.app.containerPort }}
              name: http
          args:
            {{- range .Values.app.args }}
            - {{ . | quote }}
            {{- end }}
          env:
            {{- range .Values.app.env }}
            - name: {{ .name }}
              value: {{ .value | quote }}
            {{- end }}
            - name: DATABASE_HOST
              value: {{ .Values.database.host | quote }}
            - name: DATABASE_PORT
              value: {{ .Values.database.port | quote }}
            - name: DATABASE_NAME
              value: {{ .Values.database.name | quote }}
            - name: DATABASE_USER
              value: {{ .Values.database.user | quote }}
            - name: DATABASE_PASSWORD
              value: {{ .Values.database.password | quote }}
          resources:
            {{- toYaml .Values.app.resources | nindent 12 }}
          volumeMounts:
            - name: data
              mountPath: /data
          {{- with .Values.securityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
      volumes:
        - name: migration-status
          emptyDir: {}
      {{- with .Values.securityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
  volumeClaimTemplates:
    - metadata:
        name: data
      spec:
        accessModes:
          {{- range .Values.persistence.accessModes }}
          - {{ . | quote }}
          {{- end }}
        resources:
          requests:
            storage: {{ .Values.persistence.size }}
        {{- if .Values.persistence.storageClassName }}
        storageClassName: {{ .Values.persistence.storageClassName }}
        {{- end }}

---
# FILE: templates/service-headless.yaml
apiVersion: v1
kind: Service
metadata:
  name: {{ include "stateful-app-with-migration.fullname" . }}-headless
  labels:
    {{- include "stateful-app-with-migration.labels" . | nindent 4 }}
spec:
  clusterIP: None
  ports:
    - port: {{ .Values.service.port }}
      targetPort: {{ .Values.service.targetPort }}
      protocol: TCP
      name: http
  selector:
    {{- include "stateful-app-with-migration.selectorLabels" . | nindent 4 }}

---
# FILE: templates/_helpers.tpl
{{/*
Expand the name of the chart.
*/}}
{{- define "stateful-app-with-migration.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" }}
{{- end }}

{{/*
Create a default fully qualified app name.
We truncate at 63 chars because some Kubernetes name fields are limited to this (by the DNS naming spec).
If release name contains chart name it will be used as a full name.
*/}}
{{- define "stateful-app-with-migration.fullname" -}}
{{- if .Values.fullnameOverride }}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- $name := default .Chart.Name .Values.nameOverride }}
{{- if contains $name .Release.Name }}
{{- .Release.Name | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" }}
{{- end }}
{{- end }}
{{- end }}

{{/*
Create chart name and version as used by the chart label.
*/}}
{{- define "stateful-app-with-migration.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" | trunc 63 | trimSuffix "-" }}
{{- end }}

